export const pcAcCoreStudyCourses: PcAcStudyCourse[] = [
  {
    id: "raciocinio-logico",
    title: "Raciocínio Lógico",
    subtitle: "Proposições, conectivos, equivalências, argumentos e raciocínio quantitativo",
    applicability: "Oficial Investigador de Polícia · Conhecimentos básicos do Anexo III.",
    origin: "Aulas autorais organizadas a partir dos tópicos oficiais do edital PC-AC 2026.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Proposições e conectivos lógicos",body:["Proposição é uma sentença declarativa à qual se pode atribuir, de modo definido, valor lógico verdadeiro ou falso. Perguntas, ordens e frases sem sentido declarativo não são proposições. Uma proposição simples não contém conectivo lógico; proposições compostas são formadas pela combinação de proposições.","Os conectivos mais cobrados são negação (não), conjunção (e), disjunção inclusiva (ou), condicional (se... então) e bicondicional (se e somente se). A conjunção é verdadeira quando ambas as partes são verdadeiras; a disjunção inclusiva é falsa somente quando ambas são falsas."],example:"Se P significa 'o relatório foi concluído' e Q significa 'o delegado foi comunicado', então P ∧ Q afirma que as duas situações ocorreram. P → Q afirma que, se P ocorrer, Q deverá ocorrer.",question:"Em uma conjunção P ∧ Q, quando a proposição composta é verdadeira?",answer:"Somente quando P e Q são ambas verdadeiras.",source:EDITAL},
      {title:"02 · Condicional, equivalências e negações",body:["A condicional P → Q é falsa apenas quando P é verdadeira e Q é falsa. Sua contrapositiva, ¬Q → ¬P, é logicamente equivalente à condicional original. Já a recíproca Q → P e a inversa ¬P → ¬Q não são, em geral, equivalentes à original.","A negação de uma conjunção aplica a lei de De Morgan: ¬(P ∧ Q) equivale a ¬P ∨ ¬Q. A negação de uma disjunção é ¬(P ∨ Q), equivalente a ¬P ∧ ¬Q. Em questões, negue a estrutura inteira, não apenas uma palavra isolada."],example:"A negação de 'o agente registrou a ocorrência e comunicou a chefia' é 'o agente não registrou a ocorrência ou não comunicou a chefia'.",question:"Qual é a contrapositiva de 'Se P, então Q'?",answer:"'Se não Q, então não P' (¬Q → ¬P).",source:EDITAL},
      {title:"03 · Argumentação, conjuntos e raciocínio quantitativo",body:["Um argumento é válido quando não existe situação em que todas as premissas sejam verdadeiras e a conclusão seja falsa. Validade depende da estrutura lógica, não da concordância pessoal com o conteúdo. Diagramas e relações entre conjuntos ajudam a testar inclusão, interseção, união e exclusão.","No raciocínio quantitativo, razão compara grandezas por divisão; proporção estabelece igualdade entre razões; porcentagem representa uma fração de denominador 100. Em regra de três, identifique se as grandezas variam direta ou inversamente antes de montar a relação."],example:"Se 20% de um grupo de 150 pessoas participa de uma atividade, o total correspondente é 0,20 × 150 = 30 pessoas.",question:"Um argumento é válido apenas porque sua conclusão parece plausível?",answer:"Não. A validade depende da relação lógica entre premissas e conclusão.",source:EDITAL},
      {title:"04 · Progressões, contagem e probabilidade",body:["Em uma progressão aritmética (PA), a diferença entre termos consecutivos é constante; em uma progressão geométrica (PG), a razão entre termos consecutivos é constante. O princípio fundamental da contagem multiplica as possibilidades de etapas sucessivas. Permutações ordenam todos os elementos; arranjos selecionam e ordenam parte deles; combinações selecionam sem considerar a ordem.","Para eventos A e B, P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Se forem independentes, P(A ∩ B) = P(A) × P(B). Probabilidade condicional é P(A|B) = P(A ∩ B)/P(B), quando P(B)>0."],example:"Duas etapas independentes com probabilidades de sucesso 0,8 e 0,5 têm probabilidade conjunta de 0,4.",question:"Em uma combinação, a ordem dos elementos altera o resultado?",answer:"Não. Combinações selecionam elementos sem considerar a ordem.",source:EDITAL}
    ]
  },
  {
    id: "informatica",
    title: "Noções de Informática",
    subtitle: "Sistemas operacionais, aplicativos, internet, arquivos e segurança digital",
    applicability: "Oficial Investigador de Polícia · Conhecimentos básicos do Anexo III.",
    origin: "Aulas autorais baseadas nos tópicos de Windows 11, Ubuntu, Office, LibreOffice, internet e segurança previstos no edital.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Hardware, software, arquivos e sistemas operacionais",body:["Hardware corresponde aos componentes físicos; software reúne programas e instruções. Sistema operacional administra recursos, processos, memória, dispositivos, arquivos, usuários e permissões. Windows e Linux possuem interfaces e ferramentas diferentes, mas compartilham conceitos como diretórios, contas e controle de acesso.","Extensões ajudam a identificar formatos, mas não garantem segurança nem autenticidade. Formatos abertos possuem especificações disponíveis para implementação; formatos proprietários dependem de condições definidas pelo titular. Sincronização em nuvem replica dados entre dispositivos, enquanto backup é uma cópia destinada à recuperação e deve ter política própria."],example:"Apagar um arquivo sincronizado pode propagar a exclusão aos demais dispositivos. Uma cópia de segurança independente e testada reduz o risco de perda definitiva.",question:"Sincronização automática substitui integralmente uma política de backup?",answer:"Não. Sincronização pode replicar exclusões ou corrupção; backup precisa permitir recuperação independente.",source:EDITAL},
      {title:"02 · Editores, planilhas e apresentações",body:["Em editores de texto, estilos estruturam títulos e parágrafos e permitem gerar sumário automático. Comentários registram observações; controle de alterações evidencia edições; mala direta combina uma fonte de dados com um documento-modelo para produzir comunicações individualizadas.","Planilhas trabalham com células, referências relativas e absolutas, fórmulas, funções, filtros, classificação, validação, formatação condicional e tabelas dinâmicas. Em apresentações, tema, slide mestre e modo do apresentador padronizam a exibição. Recursos semelhantes podem ter nomes ou menus diferentes entre Microsoft Office e LibreOffice."],example:"Ao copiar uma fórmula com referência absoluta como $A$1, a referência permanece fixa; uma referência relativa como A1 pode mudar conforme a fórmula é copiada.",question:"Qual é a finalidade de uma referência absoluta em uma planilha?",answer:"Manter fixa a referência à célula ou ao intervalo ao copiar a fórmula.",source:EDITAL},
      {title:"03 · Internet, e-mail, nuvem e colaboração",body:["Internet é uma rede global; intranet é uma rede privada de uma organização; extranet permite acesso controlado a usuários externos autorizados. HTTPS protege a comunicação entre navegador e servidor por criptografia e autenticação do servidor, mas não garante que o conteúdo do site seja verdadeiro.","E-mail utiliza protocolos e serviços distintos: SMTP para envio; POP3 e IMAP para recebimento, com diferenças de sincronização e armazenamento. Em ferramentas colaborativas, permissões de compartilhamento devem seguir o menor privilégio: conceder apenas o acesso necessário, pelo tempo necessário, e revogar links quando deixarem de ser úteis."],example:"Um link público de documento pode permitir acesso além da equipe pretendida. Restringir por usuário ou grupo e revisar permissões evita exposição desnecessária.",question:"HTTPS garante que todo site acessado seja legítimo e confiável?",answer:"Não. Ele protege a conexão e autentica o domínio apresentado, mas não assegura a honestidade do conteúdo.",source:EDITAL},
      {title:"04 · Segurança, autenticação e permissões",body:["Confidencialidade limita o acesso a pessoas autorizadas; integridade protege contra alterações indevidas; disponibilidade assegura acesso quando necessário. Autenticação multifator combina fatores de categorias distintas, como algo que se sabe e algo que se possui. O princípio do menor privilégio concede apenas as permissões necessárias à função.","Phishing e engenharia social tentam induzir a vítima a revelar dados ou executar ações. Links inesperados, anexos, pedidos urgentes de senha e alterações de dados bancários devem ser verificados por canal independente. Histórico de versões e logs ajudam a rastrear alterações."],example:"Antes de compartilhar uma planilha, confira destinatários, permissões, comentários e dados pessoais ocultos.",question:"Conceder edição a todos os usuários respeita o menor privilégio?",answer:"Não. O acesso deve ser limitado ao necessário para cada pessoa ou grupo.",source:CERT}
    ]
  },
  {
    id: "realidade-acre",
    title: "Realidade do Acre",
    subtitle: "História, território, povos, cultura, economia e segurança de fronteira",
    applicability: "Oficial Investigador de Polícia · Conhecimentos básicos do Anexo III.",
    origin: "Aulas autorais alinhadas aos tópicos de realidade étnica, social, geográfica, cultural, política e econômica do edital.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Formação histórica e Revolução Acreana",body:["A formação histórica do Acre está ligada à ocupação da região por brasileiros, especialmente nordestinos, à economia da borracha e às disputas de limites com a Bolívia e o Peru. A incorporação do território ao Brasil foi precedida por conflitos, negociações diplomáticas e mudanças administrativas.","A Revolução Acreana, o Tratado de Petrópolis de 1903, a organização como Território Federal e a posterior elevação a Estado são marcos diferentes de um processo histórico. Não confunda a conquista política do território com sua transformação em unidade federativa."],example:"Uma questão pode apresentar o Tratado de Petrópolis como marco da solução diplomática com a Bolívia, mas perguntar separadamente quando o Acre se tornou Estado.",question:"A assinatura do Tratado de Petrópolis e a elevação do Acre a Estado foram o mesmo acontecimento?",answer:"Não. O tratado é de 1903; a elevação a Estado ocorreu posteriormente, em 1962.",source:EDITAL},
      {title:"02 · Geografia, fronteiras e organização territorial",body:["O Acre está no extremo oeste da Região Norte e faz fronteira internacional com Peru e Bolívia, além de limites com Amazonas e Rondônia. O território apresenta clima equatorial, rede hidrográfica amazônica, áreas de floresta e importantes diferenças de acesso entre áreas urbanas, rurais e regiões de difícil deslocamento.","O estado é organizado em municípios e regionais de desenvolvimento. Para estudar, associe localização, rios, relevo, clima, vegetação, unidades de conservação e corredores de circulação. A posição fronteiriça influencia fluxos de pessoas, mercadorias, serviços e desafios de segurança pública."],example:"Uma análise de ocorrência em área de fronteira precisa considerar distância de centros urbanos, vias fluviais e terrestres, sazonalidade e cooperação entre instituições.",question:"Quais são os dois países com os quais o Acre possui fronteira internacional?",answer:"Peru e Bolívia.",source:IBGE_AC},
      {title:"03 · Povos, cultura e economia sustentável",body:["A realidade social e cultural do Acre inclui povos indígenas, populações tradicionais, comunidades extrativistas e contextos urbanos diversos. A presença de povos isolados exige respeito a protocolos de proteção e não contato; não deve ser tratada como atração turística ou como autorização para aproximação.","A economia envolve serviços, administração pública, agropecuária, extrativismo e atividades ligadas à floresta. O debate sobre desenvolvimento sustentável considera geração de renda, conservação ambiental, infraestrutura, direitos territoriais e integração regional."],example:"Uma política pública em região extrativista deve considerar os modos de vida locais e os efeitos ambientais e sociais, em vez de avaliar apenas o volume imediato de produção.",question:"Desenvolvimento sustentável considera apenas o crescimento econômico?",answer:"Não. Integra dimensões econômicas, sociais e ambientais.",source:IBGE_AC},
      {title:"04 · Ciclos da borracha, sociedade e economia",body:["A economia da borracha conectou a Amazônia aos mercados nacionais e internacionais, estimulou migrações e reorganizou relações de trabalho e ocupação territorial. No Acre, seringais, rios e rotas de circulação condicionaram a formação de povoados e a presença do Estado.","A história regional também envolve povos indígenas, trabalhadores migrantes, populações ribeirinhas e extrativistas. A economia contemporânea combina serviços, administração pública, agropecuária e extrativismo; o debate sobre desenvolvimento sustentável integra renda, conservação, infraestrutura e direitos territoriais."],example:"Ao comparar ciclos da borracha, observe conjuntura internacional, demanda, organização produtiva e efeitos demográficos no território acreano.",question:"A expansão da borracha alterou somente a produção econômica?",answer:"Não. Também influenciou migrações, rotas, povoamento e relações sociais.",source:IBGE_AC},
      {title:"05 · População, urbanização e indicadores do Acre",body:["O Censo 2022 registrou 830.018 habitantes no Acre. A Seplan informa concentração populacional em Rio Branco e Cruzeiro do Sul e predominância urbana. Indicadores demográficos devem sempre ser acompanhados do ano de referência e da fonte, pois estimativas posteriores não devem ser confundidas com resultados censitários.","Para estudar a realidade social, compare distribuição por municípios, estrutura etária, urbanização, indicadores de desenvolvimento humano, renda, educação, saúde e fluxos migratórios. Na prova, observe o recorte temporal: um dado do Censo 2022 não é uma estimativa populacional de 2026."],example:"Ao citar população do estado, identifique se o número corresponde ao Censo 2022 ou à estimativa mais recente publicada pelo IBGE.",question:"830.018 habitantes corresponde a qual referência demográfica?",answer:"Ao resultado do Censo Demográfico 2022 informado pela Seplan do Acre.",source:"https://seplan.ac.gov.br/acre-em-numeros/caracterizacao-demografica-e-social/"}
    ]
  },
  {
    id: "direito-constitucional",
    title: "Noções de Direito Constitucional",
    subtitle: "Constituição, direitos fundamentais, organização do Estado e segurança pública",
    applicability: "Oficial Investigador de Polícia · Conhecimentos jurídicos do Anexo III.",
    origin: "Aulas autorais introdutórias vinculadas ao programa do edital e à Constituição Federal.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Constituição, supremacia e normas constitucionais",body:["A Constituição ocupa posição superior no ordenamento jurídico e condiciona a validade das normas inferiores. A Constituição Federal de 1988 é escrita, promulgada, rígida e analítica. Sua supremacia sustenta o controle de constitucionalidade e orienta a interpretação do sistema jurídico.","Normas constitucionais podem ter eficácia plena, contida ou limitada, conforme a classificação doutrinária tradicional. Normas de eficácia limitada dependem de complementação normativa para desenvolver integralmente seus efeitos, mas podem produzir desde logo efeitos jurídicos mínimos, como orientar o legislador e impedir normas contrárias."],example:"Uma lei estadual não pode contrariar uma garantia constitucional sob o argumento de que atende a uma necessidade administrativa local.",question:"Uma lei ordinária pode afastar livremente uma regra da Constituição Federal?",answer:"Não. A legislação infraconstitucional deve respeitar a Constituição.",source:CF},
      {title:"02 · Direitos fundamentais e garantias",body:["O artigo 5º reúne direitos e garantias individuais e coletivos, como igualdade, liberdade, intimidade, inviolabilidade domiciliar, devido processo legal, contraditório, ampla defesa e presunção de inocência. A atuação estatal deve observar fundamento jurídico, necessidade e limites constitucionais.","Garantias processuais também se aplicam à atividade investigativa. A investigação criminal não elimina direitos do investigado, da vítima ou de terceiros. A proteção constitucional deve ser conciliada com os instrumentos legais de apuração, obtenção de prova e responsabilização."],example:"A entrada em domicílio sem consentimento depende das hipóteses constitucionais e legais; a conveniência da investigação, isoladamente, não cria autorização irrestrita.",question:"A presunção de inocência deixa de existir durante o inquérito policial?",answer:"Não. A investigação não equivale a condenação e deve respeitar as garantias constitucionais.",source:CF},
      {title:"03 · Federação, Poderes e segurança pública",body:["A República Federativa do Brasil é formada pela União, estados, Distrito Federal e municípios, com autonomia nos limites constitucionais. A separação dos Poderes organiza funções legislativas, executivas e jurisdicionais, acompanhadas de mecanismos de controle recíproco.","O artigo 144 da Constituição disciplina a segurança pública como dever do Estado, direito e responsabilidade de todos, e enumera seus órgãos. As polícias civis, dirigidas por delegados de carreira, exercem funções de polícia judiciária e apuração de infrações penais, ressalvadas as competências da União e as infrações militares."],example:"A Polícia Civil estadual não substitui a Polícia Federal nas atribuições constitucionais próprias desta última.",question:"Qual é a função constitucional central das polícias civis?",answer:"Exercer funções de polícia judiciária e apurar infrações penais, exceto as militares, ressalvada a competência da União.",source:CF},
      {title:"04 · Direitos individuais e remédios constitucionais",body:["A inviolabilidade do domicílio, a intimidade, o sigilo de comunicações e a proteção de dados limitam a atuação estatal. A Constituição prevê hipóteses específicas de ingresso domiciliar, como flagrante delito, desastre, prestação de socorro e, durante o dia, por determinação judicial. A investigação não afasta o devido processo legal, o contraditório e a ampla defesa.","Habeas corpus protege a liberdade de locomoção; mandado de segurança protege direito líquido e certo não amparado por habeas corpus ou habeas data; habeas data permite conhecer ou retificar informações pessoais em registros governamentais ou de caráter público, nos termos legais."],example:"Uma diligência domiciliar deve registrar o fundamento jurídico e as circunstâncias que autorizam o ingresso.",question:"Qual remédio constitucional tutela diretamente a liberdade de locomoção?",answer:"Habeas corpus.",source:CF}
    ]
  },
  {
    id: "direito-penal-processual",
    title: "Noções de Direito Penal e Processual Penal",
    subtitle: "Teoria do crime, penas, investigação, provas e garantias processuais",
    applicability: "Oficial Investigador de Polícia · Conhecimentos jurídicos do Anexo III. O curso introdutório não substitui o estudo integral do CP, CPP e leis especiais.",
    origin: "Aulas autorais alinhadas aos itens gerais do programa de Direito Penal e Processo Penal.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Legalidade penal e aplicação da lei no tempo",body:["O princípio da legalidade estabelece que não há crime sem lei anterior que o defina nem pena sem prévia cominação legal. A lei penal deve ser anterior ao fato para fundamentar punição, e a analogia não pode criar crime ou agravar pena em prejuízo do acusado.","A lei penal posterior mais benéfica retroage; a lei mais gravosa não retroage. Leis temporárias e excepcionais possuem disciplina própria quanto à duração e aos fatos praticados durante sua vigência. A análise exige identificar a data do fato, a sucessão de leis e a regra aplicável."],example:"Se uma lei posterior deixa de considerar criminosa determinada conduta, deve-se examinar a abolitio criminis e seus efeitos sobre a punibilidade e a execução.",question:"Uma lei penal posterior mais gravosa pode retroagir para alcançar fato anterior?",answer:"Não. A lei penal mais gravosa não retroage.",source:CP},
      {title:"02 · Fato típico, ilicitude e culpabilidade",body:["A estrutura analítica do crime, na concepção tripartida, examina fato típico, ilicitude e culpabilidade. O fato típico envolve conduta, resultado quando exigido, nexo causal e tipicidade. Dolo e culpa são elementos subjetivos relevantes para a imputação, conforme o tipo penal.","A ilicitude pode ser excluída por causas legalmente reconhecidas, como legítima defesa, estado de necessidade, estrito cumprimento do dever legal e exercício regular de direito. Culpabilidade examina, entre outros elementos, imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa."],example:"A legítima defesa não torna a conduta atípica por si só: em regra, é analisada como causa de exclusão da ilicitude, desde que presentes seus requisitos.",question:"Na estrutura tripartida, quais são os três elementos analíticos do crime?",answer:"Fato típico, ilicitude e culpabilidade.",source:CP},
      {title:"03 · Inquérito, prova e cadeia de custódia",body:["O inquérito policial é procedimento administrativo de investigação, voltado à apuração da materialidade e dos indícios de autoria. Tem caráter informativo e não é, por si só, processo judicial. A autoridade policial deve observar competências, formalidades, direitos fundamentais e prazos legais.","A cadeia de custódia documenta a história cronológica do vestígio, desde o reconhecimento e isolamento até o processamento, armazenamento e descarte. O registro de cada etapa ajuda a demonstrar identidade e integridade do material. Provas ilícitas e derivadas recebem tratamento constitucional e legal próprio."],example:"Um dispositivo eletrônico apreendido deve ser identificado, acondicionado, registrado e submetido a procedimentos técnicos documentados para preservar a confiabilidade do vestígio.",question:"A cadeia de custódia começa apenas quando o vestígio chega ao laboratório?",answer:"Não. Começa no reconhecimento do vestígio e acompanha as etapas previstas em lei.",source:CPP},
      {title:"04 · Tentativa, concurso de pessoas e prisões cautelares",body:["Na tentativa, iniciada a execução, o resultado não ocorre por circunstâncias alheias à vontade do agente. Desistência voluntária e arrependimento eficaz dependem de atuação voluntária do agente para interromper a execução ou impedir o resultado. No concurso de pessoas, coautoria e participação devem ser distinguidas conforme a contribuição e os requisitos legais.","Prisão em flagrante, preventiva e temporária possuem pressupostos e procedimentos próprios. Prisão cautelar não é antecipação de pena: exige fundamento legal e controle jurisdicional. Medidas cautelares diversas podem ser aplicadas quando adequadas e suficientes."],example:"A prisão preventiva não pode ser decretada apenas pela gravidade abstrata do delito; os requisitos legais precisam estar demonstrados no caso concreto.",question:"A prisão cautelar tem a mesma finalidade jurídica da pena após condenação definitiva?",answer:"Não. É medida processual excepcional, com pressupostos próprios, e não se confunde com pena.",source:CPP}
    ]
  },
  {
    id: "direito-administrativo",
    title: "Noções de Direito Administrativo",
    subtitle: "Princípios, atos, poderes, agentes, responsabilidade e contratações",
    applicability: "Oficial Investigador de Polícia · Conhecimentos jurídicos do Anexo III.",
    origin: "Aulas autorais introdutórias alinhadas ao programa do edital e à legislação federal de referência, sem presumir aplicação automática de normas federais a procedimentos estaduais.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Princípios expressos da Administração Pública",body:["O artigo 37 da Constituição Federal prevê legalidade, impessoalidade, moralidade, publicidade e eficiência para a Administração Pública direta e indireta de todos os Poderes e entes federativos. A legalidade administrativa exige atuação conforme o ordenamento; a impessoalidade veda favorecimentos e perseguições.","Publicidade favorece transparência, mas convive com hipóteses legais de sigilo e proteção de dados. Eficiência busca boa utilização de recursos e qualidade, sem autorizar violação da lei. Moralidade exige padrão ético-jurídico de conduta, não apenas ausência de ilegalidade formal."],example:"Um agente não pode utilizar sua função para beneficiar pessoa conhecida; isso afronta a impessoalidade e pode violar a moralidade administrativa.",question:"A eficiência permite afastar uma exigência legal considerada inconveniente?",answer:"Não. Eficiência deve ser alcançada dentro da legalidade.",source:CF},
      {title:"02 · Atos administrativos e poderes da Administração",body:["Ato administrativo é manifestação da Administração, ou de quem exerça função administrativa, que produz efeitos jurídicos sob regime de direito público. A doutrina costuma estudar competência, finalidade, forma, motivo e objeto como elementos do ato. Vícios podem levar à anulação; atos válidos podem ser revogados por razões de conveniência e oportunidade, respeitados os limites legais.","Poder hierárquico organiza e distribui funções internamente; poder disciplinar apura infrações funcionais e aplica sanções cabíveis; poder regulamentar detalha a execução da lei; poder de polícia condiciona direitos e atividades em benefício do interesse público, sempre sujeito a limites jurídicos."],example:"A Administração anula ato ilegal; a revogação, em regra, alcança ato válido que deixou de ser conveniente ou oportuno.",question:"A Administração pode revogar um ato que seja ilegal?",answer:"O ato ilegal deve ser anulado; revogação é ligada à conveniência e oportunidade de ato válido.",source:CF},
      {title:"03 · Responsabilidade civil do Estado e contratações",body:["A Constituição prevê, em regra, responsabilidade objetiva das pessoas jurídicas de direito público e das prestadoras de serviço público pelos danos que seus agentes, nessa qualidade, causem a terceiros, assegurado o direito de regresso nos casos de dolo ou culpa. A análise envolve conduta, dano e nexo causal, além das excludentes ou atenuantes reconhecidas no caso concreto.","A Lei nº 14.133/2021 estabelece normas gerais de licitações e contratos administrativos. Planejamento, motivação, transparência, competição, julgamento objetivo e gestão contratual são temas centrais. Para órgãos estaduais, devem ser observadas a lei nacional e as regulamentações estaduais aplicáveis."],example:"A contratação pública não deve ser iniciada apenas com a escolha informal de um fornecedor: exige planejamento, definição da necessidade e procedimento adequado.",question:"A responsabilidade objetiva do Estado dispensa a demonstração do dano e do nexo causal?",answer:"Não. A objetividade dispensa a prova de culpa do agente, mas não elimina os demais requisitos da responsabilidade.",source:LEI_14133},
      {title:"04 · Agentes públicos e controle administrativo",body:["Agentes públicos exercem função pública em diferentes vínculos e regimes. Cargo, emprego e função pública não são expressões equivalentes; investidura, atribuições, deveres e responsabilização dependem da Constituição e da legislação aplicável ao ente.","O controle da Administração pode ser interno, externo ou judicial, com competências e limites próprios. Processos administrativos devem observar competência, finalidade, motivação, razoabilidade, proporcionalidade e garantias de defesa quando cabíveis. A Lei nº 9.784/1999 disciplina o processo administrativo federal e não é automaticamente o estatuto geral dos processos estaduais."],example:"Ao analisar uma sanção, confira autoridade competente, fundamento normativo, fatos comprovados e oportunidade de defesa.",question:"A Lei nº 9.784/1999 rege automaticamente todo processo administrativo estadual?",answer:"Não. Ela disciplina o processo administrativo no âmbito da Administração Pública Federal, sem prejuízo de normas estaduais próprias.",source:"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}
    ]
  },
  {
    id: "legislacao-institucional",
    title: "Legislação Institucional",
    subtitle: "Organização policial, atribuições, deveres funcionais e regime jurídico",
    applicability: "Oficial Investigador de Polícia · Conhecimentos jurídicos do Anexo III. Conferir sempre a legislação estadual expressamente indicada no edital e suas alterações.",
    origin: "Aulas introdutórias com base no edital e na Lei Orgânica Nacional das Polícias Civis; não substituem a leitura da legislação estadual indicada no programa.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Organização e função institucional da Polícia Civil",body:["A Constituição Federal atribui às polícias civis, dirigidas por delegados de carreira, as funções de polícia judiciária e a apuração de infrações penais, exceto as militares, ressalvada a competência da União. A organização concreta, as unidades e a distribuição interna de atribuições dependem da Constituição estadual e das leis aplicáveis.","A Lei nº 14.735/2023 institui a Lei Orgânica Nacional das Polícias Civis e estabelece normas gerais de organização e funcionamento. Sua leitura deve ser conjugada com a legislação estadual e com as disposições específicas do edital da PC-AC."],example:"Uma norma nacional estabelece diretrizes gerais, mas a identificação da estrutura de departamentos e unidades da Polícia Civil do Acre exige consultar a lei estadual pertinente.",question:"A Lei Orgânica Nacional elimina a necessidade de consultar as normas estaduais da Polícia Civil?",answer:"Não. Normas gerais nacionais convivem com a organização e a regulamentação estadual, dentro das competências constitucionais.",source:LEI_ORGANICA},
      {title:"02 · Deveres, competências e responsabilidade funcional",body:["O exercício de função policial exige atuação dentro das competências legais, respeito aos direitos fundamentais, registro adequado dos atos, preservação de informações protegidas e observância das ordens legítimas. A responsabilidade funcional pode coexistir com responsabilidades civil e penal, conforme os fatos e os requisitos de cada regime.","Não se deve presumir que todo dever ou sanção esteja integralmente na lei orgânica nacional. Para prova, identifique no edital o diploma estadual expressamente indicado, estude seu texto atualizado e diferencie dever, proibição, infração, penalidade, competência e procedimento disciplinar."],example:"Ao receber ordem manifestamente ilegal, o servidor não deve tratá-la como autorização automática para praticar ato contrário à lei; o regime funcional e as regras de responsabilização devem ser examinados.",question:"A simples existência de uma lei orgânica nacional torna dispensável estudar o estatuto estadual citado no edital?",answer:"Não. O conteúdo estadual expressamente previsto no edital também deve ser estudado.",source:EDITAL},
      {title:"03 · Lei Orgânica Nacional e normas estaduais",body:["A Lei nº 14.735/2023 estabelece normas gerais nacionais para as Polícias Civis. Para a PC-AC, o edital também indica a Lei Complementar Estadual nº 129/2004 (Lei Orgânica da Polícia Civil), a Lei Estadual nº 2.250/2009 (PCCR) e a Lei Complementar Estadual nº 39/1993 (Estatuto dos Servidores), todas com alterações. A LC nº 129/2004 deve ser lida com as alterações posteriores, inclusive as citadas no edital, e com a Constituição do Acre.","Para cada diploma, registre número e data, âmbito de aplicação, dispositivos cobrados, alterações posteriores, órgão competente e relação com o cargo. Não atribua à lei nacional detalhes de estrutura interna, jornada ou disciplina que dependam de regulamentação estadual."],example:"Uma questão sobre diretrizes gerais pode exigir a lei nacional; uma questão sobre estrutura de unidades ou regime funcional pode exigir norma estadual específica.",question:"É seguro inferir todo o regime disciplinar estadual apenas da Lei Orgânica Nacional?",answer:"Não. É preciso consultar a legislação estadual indicada e vigente.",source:LEI_ORGANICA}
    ]
  },
  {
    id: "contabilidade-analise-financeira",
    title: "Contabilidade Geral e Análise Financeira",
    subtitle: "Patrimônio, contas, lançamentos, demonstrações e indicadores",
    applicability: "Oficial Investigador de Polícia · Conhecimentos específicos do Anexo III.",
    origin: "Aulas autorais introdutórias alinhadas ao conteúdo de Contabilidade Geral e Análise Financeira.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Patrimônio, ativo, passivo e patrimônio líquido",body:["Patrimônio é o conjunto de bens, direitos e obrigações de uma entidade. Ativo representa recursos controlados dos quais se esperam benefícios econômicos ou potencial de serviços; passivo representa obrigações presentes; patrimônio líquido é o interesse residual após a dedução dos passivos dos ativos.","A equação patrimonial básica é Ativo = Passivo + Patrimônio Líquido. O resultado de um período decorre do confronto entre receitas e despesas, observadas as regras de reconhecimento e competência. A classificação entre circulante e não circulante considera critérios contábeis próprios."],example:"Se uma entidade possui ativos de R$ 100 mil e passivos de R$ 60 mil, o patrimônio líquido, na equação simplificada, é R$ 40 mil.",question:"Na equação patrimonial básica, como se obtém o patrimônio líquido?",answer:"Subtraindo o passivo do ativo.",source:LEI_4320},
      {title:"02 · Débito, crédito e escrituração",body:["O método das partidas dobradas registra cada fato contábil com débitos e créditos de igual valor, preservando o equilíbrio dos lançamentos. Débito e crédito não significam automaticamente aumento e diminuição: o efeito depende da natureza da conta.","Contas do ativo e despesas normalmente aumentam por débito; passivo, patrimônio líquido e receitas normalmente aumentam por crédito. O plano de contas organiza os registros e permite classificar fatos de modo padronizado. A escrituração deve ser apoiada por documentação e respeitar o regime contábil aplicável."],example:"A compra de equipamento à vista pode aumentar uma conta do ativo imobilizado e reduzir disponibilidades; o lançamento deve refletir os dois efeitos.",question:"No método das partidas dobradas, a soma dos débitos de um lançamento deve ser igual à soma dos créditos?",answer:"Sim. O equilíbrio entre débitos e créditos é requisito do método.",source:LEI_4320},
      {title:"03 · Demonstrações e análise por indicadores",body:["As demonstrações contábeis organizam informações sobre posição patrimonial, desempenho e fluxos. A análise financeira utiliza comparações entre períodos, composição de contas e indicadores para avaliar liquidez, endividamento, rentabilidade e eficiência, sem interpretar um índice isoladamente.","Liquidez corrente, em sua forma usual, relaciona ativo circulante e passivo circulante. Indicadores de endividamento examinam a participação de capital de terceiros; margens relacionam resultado e receita. A interpretação depende do setor, da qualidade dos dados e da política contábil."],example:"Uma liquidez corrente superior a 1 indica, em princípio, ativo circulante maior que passivo circulante, mas não garante que todos os ativos possam ser convertidos em dinheiro no prazo necessário.",question:"Um índice de liquidez corrente acima de 1 garante solvência em qualquer circunstância?",answer:"Não. É um indicador que precisa ser analisado com prazos, composição dos ativos e demais informações.",source:LEI_4320},
      {title:"04 · Regimes contábeis e estágios da despesa pública",body:["No regime de caixa, receitas e despesas são reconhecidas conforme recebimentos e pagamentos. No regime de competência, são reconhecidas no período a que se referem, independentemente do fluxo financeiro, observadas as normas aplicáveis. Despesas incorridas e ainda não pagas podem exigir reconhecimento por competência.","Na execução orçamentária da despesa, os estágios clássicos são empenho, liquidação e pagamento. O empenho reserva dotação para obrigação assumida; a liquidação verifica o direito do credor e a entrega do objeto; o pagamento ocorre após a regular liquidação."],example:"O pagamento de uma despesa pública pressupõe sua regular liquidação, com verificação do objeto e do direito do credor.",question:"Qual estágio verifica o direito adquirido pelo credor com base nos documentos comprobatórios?",answer:"Liquidação da despesa.",source:LEI_4320}
    ]
  },
  {
    id: "estatistica",
    title: "Estatística",
    subtitle: "População, amostras, medidas descritivas, gráficos e probabilidade",
    applicability: "Oficial Investigador de Polícia · Conhecimentos específicos do Anexo III.",
    origin: "Aulas autorais introdutórias organizadas conforme os tópicos estatísticos do edital.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · População, amostra e tipos de variáveis",body:["População é o conjunto de elementos que se deseja estudar; amostra é uma parte selecionada dessa população. Censo observa todos os elementos, enquanto pesquisa amostral utiliza parte deles. A qualidade da amostra depende do método de seleção, do tamanho, da cobertura e da ausência de vieses relevantes.","Variáveis qualitativas representam categorias; quantitativas representam valores numéricos e podem ser discretas ou contínuas. A escala de mensuração e o tipo de variável orientam quais resumos e gráficos fazem sentido."],example:"O número de ocorrências por unidade é uma variável quantitativa discreta; o tipo de ocorrência é qualitativa nominal.",question:"Uma amostra é necessariamente igual à população?",answer:"Não. É um subconjunto selecionado para representar ou investigar a população.",source:EDITAL},
      {title:"02 · Média, mediana, moda e dispersão",body:["A média aritmética é a soma dos valores dividida pela quantidade de observações; a mediana é o valor central após ordenar os dados; a moda é o valor mais frequente. A mediana costuma ser menos sensível a valores extremos do que a média.","Amplitude, variância e desvio-padrão descrevem dispersão. Desvio-padrão elevado indica maior afastamento dos dados em relação à média, na unidade original da variável. Medidas de posição e dispersão devem ser interpretadas em conjunto."],example:"No conjunto 2, 3, 3, 4 e 18, a média é 6 e a mediana é 3; o valor extremo eleva a média.",question:"Qual medida de tendência central costuma ser menos afetada por um valor extremo isolado?",answer:"A mediana.",source:EDITAL},
      {title:"03 · Probabilidade e interpretação de dados",body:["Probabilidade varia de 0 a 1 e expressa a medida de possibilidade de um evento em um modelo probabilístico. Para eventos equiprováveis, pode-se calcular a razão entre casos favoráveis e casos possíveis. A probabilidade da união exige considerar a interseção para evitar dupla contagem.","Gráficos e tabelas precisam ser lidos observando título, unidade, período, fonte, escala e denominadores. Uma porcentagem sem informar a base de comparação pode induzir a conclusões equivocadas; correlação entre variáveis não demonstra, por si só, causalidade."],example:"Se 20 de 100 registros pertencem a uma categoria, sua frequência relativa é 20%. Se o universo mudar, a mesma quantidade absoluta pode representar outra proporção.",question:"A existência de correlação entre duas variáveis prova que uma causa a outra?",answer:"Não. Correlação indica associação; causalidade exige análise adicional.",source:EDITAL},
      {title:"04 · Frequências, gráficos e distribuições",body:["Distribuições de frequências organizam observações em categorias ou classes, apresentando frequências absolutas, relativas e acumuladas. Gráficos de barras comparam categorias; histogramas representam distribuições quantitativas agrupadas em intervalos; gráficos de linhas ajudam a observar evolução temporal.","A distribuição binomial modela número de sucessos em quantidade fixa de tentativas independentes, com probabilidade constante. A distribuição normal é contínua e simétrica, definida por média e desvio-padrão. Correlação não prova causalidade e toda tabela deve ser lida com unidade, período, escala e denominador."],example:"Se 15 de 60 ocorrências pertencem a uma categoria, sua frequência relativa é 25%.",question:"O histograma é especialmente utilizado para representar que tipo de dado?",answer:"Dados quantitativos organizados em classes ou intervalos.",source:EDITAL}
    ]
  },
  {
    id: "ti-seguranca",
    title: "Tecnologia da Informação e Segurança da Informação",
    subtitle: "Dados, redes, bancos de dados, controles de acesso e resposta a incidentes",
    applicability: "Oficial Investigador de Polícia · Conhecimentos específicos do Anexo III.",
    origin: "Aulas autorais introdutórias alinhadas aos tópicos de TI e segurança da informação do edital.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Dados, sistemas de informação e bancos de dados",body:["Dado é um registro bruto; informação resulta de organização e contexto que permitem interpretação; conhecimento envolve compreensão e aplicação da informação. Sistemas de informação combinam pessoas, processos, dados e tecnologia para apoiar operações e decisões.","Banco de dados organiza dados de forma estruturada. Em bancos relacionais, tabelas representam entidades, linhas representam registros e colunas representam atributos. Chaves primárias identificam registros; chaves estrangeiras estabelecem relações. Integridade, consistência, disponibilidade e controle de acesso são requisitos importantes."],example:"Uma tabela de ocorrências pode usar um identificador único por registro e relacionar cada ocorrência a uma unidade por chave estrangeira.",question:"Em um banco relacional, qual é a função típica de uma chave primária?",answer:"Identificar unicamente cada registro da tabela.",source:EDITAL},
      {title:"02 · Redes, serviços e computação em nuvem",body:["Redes permitem a comunicação entre dispositivos por meios físicos ou sem fio. Endereços IP identificam interfaces em redes; DNS associa nomes de domínio a endereços; protocolos definem regras de comunicação. A distinção entre rede local, internet e serviços remotos ajuda a compreender disponibilidade e segurança.","Computação em nuvem oferece recursos computacionais por rede, com modelos de serviço e implantação diferentes. Armazenamento, processamento e aplicações em nuvem dependem de gestão de identidade, permissões, configuração segura, continuidade e avaliação de fornecedores."],example:"Um serviço pode estar disponível pela internet e ainda assim exigir autenticação forte, autorização por perfil e registro de atividades.",question:"O DNS tem como função principal traduzir nomes de domínio em informações de endereçamento?",answer:"Sim. Ele permite localizar serviços por nomes, entre outras funções do sistema de nomes.",source:EDITAL},
      {title:"03 · Segurança, LGPD e resposta a incidentes",body:["Confidencialidade limita o acesso a pessoas autorizadas; integridade protege contra alterações indevidas; disponibilidade assegura acesso quando necessário. Autenticação verifica identidade; autorização define permissões; auditoria registra e permite examinar atividades. O princípio do menor privilégio reduz o impacto de contas comprometidas.","Phishing tenta induzir a vítima a revelar dados ou executar ações; malware abrange software malicioso; ransomware pode bloquear ou criptografar dados para extorsão. A resposta a incidentes exige identificar, conter, preservar evidências, erradicar a causa, recuperar serviços e registrar aprendizados. O tratamento de dados pessoais deve observar a LGPD e as bases legais aplicáveis."],example:"Diante de mensagem suspeita, não se deve abrir anexos ou fornecer credenciais; a mensagem deve ser reportada pelo canal institucional e tratada conforme o procedimento de segurança.",question:"Qual princípio recomenda conceder somente as permissões necessárias à função?",answer:"Princípio do menor privilégio.",source:CERT},
      {title:"04 · Criptografia, hash e evidência digital",body:["Criptografia protege a informação contra leitura não autorizada e pode usar chaves simétricas ou assimétricas. Funções hash produzem resumos usados para verificar integridade; hash não é criptografia reversível nem prova automática de autoria. Assinaturas digitais, certificados e registros de auditoria contribuem para autenticidade e rastreabilidade.","Na evidência digital, procedimentos de coleta, cópia forense, registro de ferramenta, horário, responsável e hash ajudam a documentar preservação. A cadeia de custódia deve ser observada desde o reconhecimento do vestígio e durante as etapas de manuseio e armazenamento."],example:"Calcular e registrar o hash de uma imagem forense na aquisição e na análise permite verificar se o arquivo permaneceu idêntico.",question:"Uma função hash permite recuperar o conteúdo original por simples operação inversa?",answer:"Não. Hash é unidirecional e pode ser usado para verificar integridade.",source:CERT}
    ]
  },
  {
    id: "analise-dados-informacoes",
    title: "Análise de Dados e Informações",
    subtitle: "Qualidade de dados, cruzamento de registros, vínculos, séries temporais e relatórios analíticos",
    applicability: "Oficial Investigador de Polícia · Conhecimentos específicos do Anexo III, item 2.2.",
    origin: "Aulas autorais organizadas diretamente pelos dez eixos do conteúdo programático oficial PC-AC 2026.",
    updated: "Estrutura inicial · 13/11/2026",
    lessons: [
      {title:"01 · Dados, informação, fontes e qualidade",body:["Dados estruturados seguem um esquema definido, como tabelas relacionais; semiestruturados possuem organização parcial, como JSON e XML; não estruturados incluem textos livres, imagens, áudio e vídeo. Informação é o dado contextualizado e interpretável para uma finalidade.","A qualidade da informação pode ser avaliada por completude, exatidão, consistência, atualidade, unicidade, validade e rastreabilidade. A confiabilidade da fonte deve ser examinada separadamente da aparência do registro: um dado bem formatado pode ser falso, incompleto ou desatualizado."],example:"Dois registros com grafias diferentes do mesmo nome podem representar a mesma pessoa, mas a correspondência precisa de outros identificadores e validação.",question:"Um registro completo e bem formatado é necessariamente verdadeiro?",answer:"Não. Completude e formatação não garantem exatidão ou confiabilidade da fonte.",source:EDITAL},
      {title:"02 · Padronização, duplicidades e dados incompletos",body:["O tratamento de dados começa pela preservação da fonte original e pela criação de cópia de trabalho. Padronização uniformiza formatos de datas, telefones, endereços, nomes e categorias; validação identifica valores incompatíveis; deduplicação localiza registros possivelmente repetidos sem eliminar evidências de forma automática.","Dados ausentes precisam ser identificados e classificados. Campo vazio não significa necessariamente zero, resposta negativa ou inexistência do fato. Imputação ou preenchimento só deve ocorrer com método explícito e justificativa; em análise investigativa, lacunas devem permanecer sinalizadas quando não houver base para completá-las."],example:"Uma planilha pode conter datas em formatos diferentes e números de telefone com ou sem DDD; a normalização facilita a comparação sem alterar a fonte preservada.",question:"Um campo vazio pode ser convertido automaticamente em zero?",answer:"Não. A ausência precisa ser interpretada conforme o significado do campo e a origem do dado.",source:EDITAL},
      {title:"03 · Cruzamento, correspondência e análise de vínculos",body:["Cruzamento de dados compara registros de fontes distintas para identificar correspondências, divergências, recorrências e relações. Chaves de ligação podem ser identificadores exatos, mas também podem existir correspondências aproximadas, que exigem validação humana e registro do critério utilizado.","Análise de vínculos representa relações entre pessoas, organizações, endereços, telefones, contas, eventos e registros. Diagramas podem mostrar conexões diretas e indiretas, frequência, intensidade e temporalidade. A existência de vínculo ou contato não prova, isoladamente, participação em ilícito."],example:"Dois registros que compartilham um telefone podem indicar contato ou uso comum, mas é necessário verificar titularidade, período, contexto e outras evidências.",question:"Uma conexão em diagrama de vínculos prova automaticamente a prática de crime?",answer:"Não. Ela aponta uma relação a investigar e precisa ser interpretada com contexto e outras evidências.",source:EDITAL},
      {title:"04 · Linhas do tempo, comunicação e análise geográfica",body:["A análise temporal organiza eventos por data e hora, identifica intervalos, sequências, sobreposições e mudanças de padrão. Antes de comparar registros, confira fuso horário, horário de verão quando pertinente, formato de data, precisão do relógio e origem do carimbo temporal.","A análise de comunicações pode observar frequência, duração, sequência de contatos e horários, respeitando autorização e limites legais de acesso. A análise geográfica utiliza endereços, coordenadas, distâncias e trajetos; erros de geocodificação, precisão e escala podem distorcer conclusões."],example:"Uma linha do tempo deve indicar a origem de cada horário e se os registros foram convertidos para um mesmo fuso antes de comparar eventos.",question:"Por que é necessário verificar o fuso horário antes de ordenar eventos digitais?",answer:"Porque registros em fusos diferentes podem parecer fora de ordem se forem comparados sem normalização.",source:EDITAL},
      {title:"05 · Hipóteses, relatórios e limitações analíticas",body:["Análise distingue fatos observados, inferências e hipóteses explicativas. Uma hipótese deve ser comparada com explicações alternativas e confrontada com dados que possam confirmá-la ou enfraquecê-la. Contradições e lacunas não devem ser ocultadas para produzir uma narrativa aparentemente coerente.","Relatórios analíticos apresentam método, fontes, critérios de seleção, resultados, limitações e conclusões proporcionais às evidências. Tabelas, gráficos e diagramas precisam ser legíveis, indicar unidades e períodos e evitar afirmações causais quando os dados mostram apenas associação."],example:"Um relatório pode afirmar que dois eventos ocorreram próximos no tempo e no espaço, mas não deve concluir que um causou o outro sem evidências adicionais.",question:"Qual é a boa prática quando os dados são insuficientes para uma conclusão?",answer:"Explicitar a limitação, registrar a lacuna e evitar apresentar hipótese como fato comprovado.",source:EDITAL}
    ]
  }
];
